package com.dailyhelp.config;
import jakarta.servlet.http.HttpServletResponse; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.csrf.CookieCsrfTokenRepository; import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler; import org.springframework.web.cors.*;
@Configuration public class SecurityConfig {
 @Value("${app.cors.allowed-origin:http://localhost:5173}") private String allowedOrigin;
 @Value("${app.cookies.secure:false}") private boolean secureCookies;
 @Value("${app.cookies.same-site:Lax}") private String sameSite;
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean SecurityFilterChain securityFilterChain(HttpSecurity http)throws Exception {CookieCsrfTokenRepository csrf=CookieCsrfTokenRepository.withHttpOnlyFalse(); csrf.setCookiePath("/"); csrf.setCookieCustomizer(cookie->cookie.secure(secureCookies).sameSite(sameSite)); CsrfTokenRequestAttributeHandler csrfHandler=new CsrfTokenRequestAttributeHandler(); http.cors(Customizer.withDefaults()).csrf(c->c.csrfTokenRepository(csrf).csrfTokenRequestHandler(csrfHandler)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/register","/api/auth/login","/api/csrf","/actuator/health","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().anyRequest().authenticated()).formLogin(f->f.disable()).httpBasic(b->b.disable()).logout(l->l.logoutUrl("/api/auth/logout").logoutSuccessHandler((req,res,auth)->res.setStatus(HttpServletResponse.SC_NO_CONTENT)).invalidateHttpSession(true).deleteCookies("JSESSIONID","XSRF-TOKEN")).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->res.sendError(401)).accessDeniedHandler((req,res,ex)->res.sendError(403))).sessionManagement(s->s.sessionFixation(f->f.migrateSession())); return http.build();}
 @Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of(allowedOrigin));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Content-Type","X-XSRF-TOKEN","X-Requested-With"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}